// Kuwahara-Oelbild: vier 3x3-Quadranten, der mit der kleinsten Varianz
// gewinnt — Flaechen werden malerisch ruhig, Kanten bleiben stehen.
vec4 farbe(vec2 uv, vec4 src)
{
    vec2 px = 1.0 / uResolution;
    vec3 beste = src.rgb;
    float besteVar = 1e9;
    for (int q = 0; q < 4; ++q)
    {
        vec2 richtung = vec2(q == 0 || q == 3 ? 1.0 : -1.0,
                             q < 2 ? 1.0 : -1.0);
        vec3 summe = vec3(0.0);
        vec3 summe2 = vec3(0.0);
        for (int y = 0; y < 3; ++y)
        {
            for (int x = 0; x < 3; ++x)
            {
                vec3 c = texture(uTex, uv + px * richtung * vec2(float(x), float(y))).rgb;
                summe += c;
                summe2 += c * c;
            }
        }
        vec3 mittel = summe / 9.0;
        vec3 varianz = summe2 / 9.0 - mittel * mittel;
        float v = varianz.r + varianz.g + varianz.b;
        if (v < besteVar) { besteVar = v; beste = mittel; }
    }
    return vec4(beste, 1.0);
}
